import{_ as a,o,c as r,a2 as t}from"./chunks/framework.DzNHXt93.js";const m=JSON.parse('{"title":"AtLeastOnceQueue — takoform_at_least_once_queue","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/at-least-once-queue.md","filePath":"proposals/edge/at-least-once-queue.md"}'),s={name:"proposals/edge/at-least-once-queue.md"};function n(i,e,d,c,u,l){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="atleastoncequeue-—-takoform-at-least-once-queue" tabindex="-1">AtLeastOnceQueue — <code>takoform_at_least_once_queue</code> <a class="header-anchor" href="#atleastoncequeue-—-takoform-at-least-once-queue" aria-label="Permalink to &quot;AtLeastOnceQueue — `takoform_at_least_once_queue`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A worker defers work — webhooks, fan-out, retries — by sending messages that a consumer worker processes asynchronously. Producers use <code>module-worker.queue-producer</code> bindings; consumption is the <a href="./queue-consumer.html">QueueConsumer</a> attachment.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>identity</code>.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>Exactly the <code>edge.queue@1.0.0</code> contract: send/sendBatch on the producer side, and per-message and per-batch settlement on the consumer side, with at-least-once delivery and no ordering guarantee. An accepted message is delivered one or more times, possibly out of send order; consumers must be idempotent. <code>messageRetentionSeconds</code> (60..1209600) bounds how long an undelivered message survives; <code>deliveryDelaySeconds</code> (0..43200) defers deliverability. Both are portable retention/delay semantics, not host capacity.</p><p>A message body is opaque BYTES, a message identity is stable across redeliveries, and the acceptance timestamp does not move. A queue has AT MOST ONE consumer: two would give one queue two retry policies and two dead-letter destinations with no rule deciding which message got which (decision 0020).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>The delivery guarantee is the contract consumers program against. There is deliberately no ordering field: an ordering selector would change consumer correctness requirements invisibly.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>A FIFO queue, an exactly-once-effect queue, or a multi-consumer published stream each change delivery or ordering semantics and are different Forms.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p><code>edge.queue@1.0.0</code>.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None; it is a binding target (<code>module-worker.queue-producer</code>) and an attachment target (QueueConsumer).</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Deleting a queue with producer bindings or consumers must fail with <code>dependency_in_use</code>. Retained messages are destroyed with the queue.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The at-least-once queue of a proven edge platform. The retained v1alpha2 <code>Queue</code> candidate, whose open <code>ordering</code> enum this Form replaces by fixing one delivery shape.</p>',20)])])}const p=a(s,[["render",n]]);export{m as __pageData,p as default};
